import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import * as prettier from "prettier";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = JSON.parse(
  fs.readFileSync(
    path.join(root, "packages/icons/src/owned/navigation-glyphs.json"),
    "utf8",
  ),
);
const note =
  "Generated by scripts/generate-navigation-glyphs.mjs from the original Kozmos navigation artwork. Edit the JSON source, never this file.";
const arity = { M: 2, L: 2, C: 6, Z: 0 };
export function parsePath(value) {
  const tokens = value.match(/[MLCZ]|-?\d+(?:\.\d+)?/g) ?? [];
  if (tokens.join("") !== value.replace(/\s/g, ""))
    throw new Error(`Unsupported path: ${value}`);
  const commands = [];
  while (tokens.length) {
    const op = tokens.shift();
    if (!(op in arity)) throw new Error(`Expected command: ${op}`);
    const args = tokens.splice(0, arity[op]).map(Number);
    if (
      args.length !== arity[op] ||
      args.some((n) => !Number.isFinite(n) || n < 0 || n > 24)
    )
      throw new Error(`Invalid coordinates: ${value}`);
    commands.push({ op, args });
  }
  if (commands[0]?.op !== "M") throw new Error("A path must begin with M");
  return commands;
}
const swiftPoint = (x, y) => `CGPoint(x: ${x}, y: ${y})`;
const swiftCommand = ({ op, args: a }) =>
  op === "M"
    ? `p.move(to: ${swiftPoint(...a)})`
    : op === "L"
      ? `p.addLine(to: ${swiftPoint(...a)})`
      : op === "C"
        ? `p.addCurve(to: ${swiftPoint(a[4], a[5])}, control1: ${swiftPoint(a[0], a[1])}, control2: ${swiftPoint(a[2], a[3])})`
        : "p.closeSubpath()";
const kotlinCommand = ({ op, args }) =>
  `${{ M: "moveTo", L: "lineTo", C: "curveTo", Z: "close" }[op]}(${args.map((n) => `${n}f`).join(", ")})`;
const glyphs = source.glyphs;
if (
  new Set(glyphs.map((g) => g.kind)).size !== glyphs.length ||
  new Set(glyphs.map((g) => g.name)).size !== glyphs.length
)
  throw new Error("Duplicate glyph identity");
const ts = `// ${note}\nimport { createPointrIcon } from "../pointr/createPointrIcon";\n\n${glyphs.map((g) => `export const ${g.name} = /* @__PURE__ */ createPointrIcon("${g.name}", ${JSON.stringify(g.paths.map((d) => ({ d })))});`).join("\n")}\n`;
const swift = `// ${note}\nimport SwiftUI\n\nenum KozmosNavigationGlyphPaths {\n    static func path(_ kind: String) -> Path? {\n        var p = Path()\n        switch kind {\n${glyphs
  .map(
    (g) =>
      `        case "${g.kind}":\n${g.paths
        .flatMap(parsePath)
        .map((c) => `            ${swiftCommand(c)}`)
        .join("\n")}`,
  )
  .join(
    "\n",
  )}\n        default: return nil\n        }\n        return p\n    }\n}\n`;
const kotlin = `// ${note}\npackage com.kozmos.utils\n\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.graphics.SolidColor\nimport androidx.compose.ui.graphics.StrokeCap\nimport androidx.compose.ui.graphics.StrokeJoin\nimport androidx.compose.ui.graphics.vector.ImageVector\nimport androidx.compose.ui.graphics.vector.path\nimport androidx.compose.ui.unit.dp\n\ninternal object KozmosNavigationGlyphs {\n${glyphs
  .map(
    (g) =>
      `    val ${g.name}: ImageVector by lazy {\n        ImageVector.Builder(name = "${g.name}", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f, autoMirror = false).apply {\n${g.paths
        .map(
          (p) =>
            `            path(fill = null, stroke = SolidColor(Color.Black), strokeLineWidth = 2f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round) {\n${parsePath(
              p,
            )
              .map((c) => `                ${kotlinCommand(c)}`)
              .join("\n")}\n            }`,
        )
        .join("\n")}\n        }.build()\n    }`,
  )
  .join("\n")}\n}\n`;
const outputs = new Map([
  ["packages/icons/src/owned/navigation.generated.ts", ts],
  ["packages/ios/Sources/Utilities/NavigationGlyphs.generated.swift", swift],
  [
    "packages/android/src/main/java/com/kozmos/utils/NavigationGlyphs.generated.kt",
    kotlin,
  ],
]);
for (const [relative, content] of outputs) {
  const filename = path.join(root, relative);
  const canonical = relative.endsWith(".ts")
    ? await prettier.format(content, {
        ...(await prettier.resolveConfig(filename)),
        filepath: filename,
      })
    : content;
  if (process.argv.includes("--check")) {
    if (
      !fs.existsSync(filename) ||
      fs.readFileSync(filename, "utf8") !== canonical
    )
      throw new Error(`Stale navigation glyphs: ${relative}`);
  } else fs.writeFileSync(filename, canonical);
}
console.log(
  `Navigation glyphs: ${glyphs.length} shared vectors ${process.argv.includes("--check") ? "verified" : "generated"}`,
);
